     6	/**
     7	 * The MHPCO price list: what the office charges as a base premium for the items it
     8	 * covers, before any modifier that depends on the customer or the contract.
     9	 */
    10	public final class MhpcoPriceList {
    11	
    12	    /** Base premium in G per main item type. */
    13	    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_BY_TYPE = Map.of(
    14	            "sword", 100,
    15	            "amulet", 60,
    16	            "staff", 80,
    17	            "potion", 40);
    18	
    19	    /**
    20	     * Components are a family of small item types the MHPCO prices alike: every
    21	     * component costs the same base premium, whatever its type.
    22	     */
    23	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    24	
    25	    private static final int COMPONENT_BASE_PREMIUM = 25;
    26	
    27	    /** A building block of exactly 3 alike components is offered at a special price. */
    28	    private static final int COMPONENT_BLOCK_SIZE = 3;
    29	    private static final int COMPONENT_BLOCK_BASE_PREMIUM = 60;
    30	
    31	    /**
    32	     * Placeholder for types not yet in the price list. The specification treats an
    33	     * unknown type as an error; until that behavior is implemented, unlisted types
    34	     * fall back to the sword price rather than to an invented "unlisted item" price.
    35	     */
    36	    private static final int UNLISTED_TYPE_PLACEHOLDER_PREMIUM =
    37	            MAIN_ITEM_BASE_PREMIUM_BY_TYPE.get("sword");
    38	
    39	    private MhpcoPriceList() {
    40	    }
