    44	     * group of alike components priced together so building blocks can be recognised.
    45	     */
    46	    public static double policyBasePremiumOf(List<Item> items) {
    47	        double mainItems = items.stream()
    48	                .filter(item -> !isComponent(item))
    49	                .mapToDouble(MhpcoPriceList::mainItemBasePremiumOf)
    50	                .sum();
    51	        double components = alikeComponentCounts(items).values().stream()
    52	                .mapToDouble(MhpcoPriceList::alikeComponentsBasePremiumOf)
    53	                .sum();
