import java.math.BigDecimal;
import java.math.RoundingMode;
public class ExactProbe {
    static BigDecimal rate(int p){ return BigDecimal.valueOf(p,2); }
    public static void main(String[] a){
        BigDecimal base = BigDecimal.valueOf(100);
        // the multiplicative chain that broke under double
        BigDecimal v = base.add(base.multiply(rate(10)));
        System.out.println("100 + 10% = " + v + " -> " + v.setScale(0,RoundingMode.CEILING));
        // the full integration example rates stacked
        BigDecimal s = base
            .add(base.multiply(rate(50)))
            .add(base.multiply(rate(30)))
            .subtract(base.multiply(rate(20)))
            .add(base.multiply(rate(10)))
            .subtract(base.multiply(rate(15)));
        System.out.println("stacked = " + s + " +fee -> " + s.add(BigDecimal.valueOf(5)).setScale(0,RoundingMode.CEILING));
        // spec rounding example 197.5
        BigDecimal r = BigDecimal.valueOf(1975,1);
        System.out.println("197.5 -> " + r.setScale(0,RoundingMode.CEILING));
    }
}
